from pathlib import Path
import csv
from locust import HttpUser, task, constant
# Original bug: each worker reads the entire same pool.
POOL = list(csv.DictReader(Path('perfspec/catalog/assets/locust/catalog.csv').open()))
class CatalogUser(HttpUser):
    wait_time = constant(1)
    @task
    def catalog(self):
        row = POOL.pop(0)
        with self.client.get('/catalog/' + row['item_id'], name='catalog', catch_response=True) as response:
            if response.status_code != 200:
                response.failure('unexpected status')
